# Enzymatic scavenging of reactive oxygen species: superoxide dismutase (SOD) and the ascorbate-glutathione
# (Foyer-Halliwell-Asada) cycle, as in chloroplasts, mitochondria, peroxisomes and the cytosol; catalase (CAT) in
# peroxisomes. APX: ascorbate peroxidase; MDHA: monodehydroascorbate; DHA: dehydroascorbate; MDHAR, DHAR,
# GR: monodehydroascorbate reductase, dehydroascorbate reductase, glutathione reductase. Reducing power comes from
# NAD(P)H generated by photosynthesis or respiration.
import wikibio as bio

P = bio.P
fig, ax = bio.canvas(24.0, 11.0)


def chem(xy, text, token="metabolite", w=2.4, h=0.8):
    bio.box(ax, xy, w, h, token=token, text=text, size="small", radius=0.38)


def enz(xy, text):
    bio.label(ax, xy, text, size="small", bold=True, color=P.edge("enzyme"))


chem((1.8, 9.2), "O₂•⁻", token="negative", w=1.8)
chem((6.4, 9.2), "H₂O₂", token="negative", w=1.8)
chem((10.8, 9.2), "H₂O", token="neutral", w=1.8)
bio.reaction(ax, (2.75, 9.2), (5.45, 9.2), side=("2 H⁺", "O₂"))
enz((4.1, 8.4), "SOD")
bio.reaction(ax, (7.35, 9.2), (9.85, 9.2))
enz((8.6, 9.65), "APX")
# catalase branch
bio.arrow(ax, (6.4, 9.65), (6.4, 10.45), kind="process")
bio.label(ax, (6.75, 10.3), "CAT (peroxisome): 2 H₂O₂ → 2 H₂O + O₂", size="tiny", ha="left")

# ascorbate pool
chem((8.6, 6.6), "Ascorbate", token="positive", w=2.8)
chem((14.6, 6.6), "MDHA", token="highlight", w=2.2)
chem((14.6, 3.4), "DHA", token="highlight", w=2.2)
bio.arrow(ax, (8.6, 7.05), (8.6, 9.05), kind="process")
bio.arrow(ax, (9.2, 9.05), (13.8, 7.05), kind="process")
bio.label(ax, (12.6, 8.55), "2 Asc → 2 MDHA", size="tiny", ha="left")
bio.arrow(ax, (13.5, 6.35), (10.05, 6.35), kind="process")
enz((11.8, 5.95), "MDHAR")
bio.label(ax, (11.8, 5.55), "NAD(P)H → NAD(P)⁺", size="tiny")
bio.arrow(ax, (14.6, 6.15), (14.6, 3.85), kind="process", dashed=True)
bio.label(ax, (15.0, 5.0), "spontaneous", size="tiny", ha="left")
bio.label(ax, (15.0, 4.6), "disproportionation", size="tiny", ha="left")
bio.arrow(ax, (13.5, 3.4), (9.0, 6.15), kind="process")
enz((11.6, 4.95), "DHAR")

# glutathione pool
chem((8.6, 1.4), "2 GSH", token="positive", w=2.2)
chem((14.6, 1.4), "GSSG", token="highlight", w=2.2)
bio.arrow(ax, (9.7, 1.6), (13.5, 1.6), kind="process", bend=0.0)
bio.label(ax, (11.75, 2.3), "electrons for DHAR", size="tiny", ha="left")
bio.arrow(ax, (13.5, 1.1), (9.7, 1.1), kind="process")
enz((11.6, 0.55), "GR")
bio.label(ax, (11.6, 0.15), "NADPH → NADP⁺", size="tiny")
ax.plot([11.6, 11.6], [4.6, 1.85], color=P.muted(), lw=0.8, ls=":")

# non-enzymatic antioxidants and sources
bio.label(ax, (18.2, 10.2), "ROS sources", size="small", bold=True, ha="left")
for i, t in enumerate(["PSI (Mehler reaction): O₂•⁻", "PSII: ¹O₂", "photorespiration: H₂O₂",
                       "mitochondrial ETC: O₂•⁻", "NADPH oxidases (RBOH)"]):
    bio.label(ax, (18.2, 9.6 - 0.45 * i), "• " + t, size="tiny", ha="left")
bio.label(ax, (18.2, 6.9), "Other antioxidants", size="small", bold=True, ha="left")
for i, t in enumerate(["α-tocopherol (membranes)", "carotenoids (quench ¹O₂)", "flavonoids, proline",
                       "peroxiredoxin–thioredoxin", "glutathione peroxidase"]):
    bio.label(ax, (18.2, 6.3 - 0.45 * i), "• " + t, size="tiny", ha="left")
